-- Ignored authoring draft. Root promotes/applies after independent review.
begin;
create table app.parent_conversation_policies(school_id uuid not null references app.schools(id),id uuid not null default gen_random_uuid(),version integer not null check(version>0),enabled boolean not null,reason text not null check(length(btrim(reason))between 1 and 1000),approved_by uuid not null,approved_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,version),foreign key(school_id,approved_by)references app.memberships(school_id,actor_id));
create table app.parent_conversations(school_id uuid not null,id uuid not null default gen_random_uuid(),learner_id uuid not null,parent_id uuid not null,teacher_id uuid not null,class_id uuid not null,subject_id uuid not null,title text not null check(length(btrim(title))between 1 and 200),created_by uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id),foreign key(school_id,parent_id)references app.memberships(school_id,actor_id),foreign key(school_id,teacher_id)references app.memberships(school_id,actor_id),foreign key(school_id,created_by)references app.memberships(school_id,actor_id),foreign key(school_id,class_id)references app.classes(school_id,id),foreign key(school_id,subject_id)references app.subjects(school_id,id),check(learner_id<>parent_id and learner_id<>teacher_id and parent_id<>teacher_id));
create table app.parent_conversation_messages(school_id uuid not null,id uuid not null default gen_random_uuid(),conversation_id uuid not null,sender_id uuid not null,body text not null check(length(btrim(body))between 1 and 4000),sent_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,id,conversation_id),foreign key(school_id,conversation_id)references app.parent_conversations(school_id,id),foreign key(school_id,sender_id)references app.memberships(school_id,actor_id));
create table app.parent_conversation_reads(school_id uuid not null,message_id uuid not null,reader_id uuid not null,read_at timestamptz not null default clock_timestamp(),primary key(school_id,message_id,reader_id),foreign key(school_id,message_id)references app.parent_conversation_messages(school_id,id),foreign key(school_id,reader_id)references app.memberships(school_id,actor_id));
create table app.parent_conversation_reports(school_id uuid not null,id uuid not null default gen_random_uuid(),message_id uuid not null,reporter_id uuid not null,reason text not null check(length(btrim(reason))between 1 and 1000),created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,message_id,reporter_id),foreign key(school_id,message_id)references app.parent_conversation_messages(school_id,id),foreign key(school_id,reporter_id)references app.memberships(school_id,actor_id));
create table app.parent_conversation_moderations(school_id uuid not null,id uuid not null default gen_random_uuid(),message_id uuid not null,version integer not null check(version>0),action text not null check(action in('HIDE','RESTORE')),reason text not null check(length(btrim(reason))between 1 and 1000),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,message_id,version),foreign key(school_id,message_id)references app.parent_conversation_messages(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create table app.parent_conversation_states(school_id uuid not null,id uuid not null default gen_random_uuid(),conversation_id uuid not null,version integer not null check(version>0),state text not null check(state in('OPEN','PAUSED')),reason text not null check(length(btrim(reason))between 1 and 1000),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,conversation_id,version),foreign key(school_id,conversation_id)references app.parent_conversations(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create index parent_conversation_message_page on app.parent_conversation_messages(school_id,conversation_id,id);
create index parent_conversation_learner_page on app.parent_conversations(school_id,learner_id,id);
create function internal.parent_conversation_enabled(target_school uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".can_access_school(target_school)and"authorization".has_entitlement(target_school,'community')and(select p.enabled from app.parent_conversation_policies p where p.school_id=target_school order by p.version desc limit 1),false)$$;
create function internal.parent_conversation_tuple_allowed(target_school uuid,target_learner uuid,target_parent uuid,target_teacher uuid,target_class uuid,target_subject uuid)returns boolean language sql stable security definer set search_path=''as $$
select coalesce(internal.parent_conversation_enabled(target_school)and exists(select 1 from app.classes c join app.enrollments e on e.school_id=c.school_id and e.class_id=c.id join app.parent_relationships r on r.school_id=e.school_id and r.student_actor_id=e.student_actor_id join app.teacher_assignments t on t.school_id=c.school_id and t.class_id=c.id where c.school_id=target_school and c.id=target_class and c.status='active'and e.student_actor_id=target_learner and r.parent_actor_id=target_parent and t.teacher_actor_id=target_teacher and t.subject_id=target_subject and e.status='active'and r.status='active'and t.status='active'and e.effective_from<=now()and(e.effective_to is null or e.effective_to>now())and r.effective_from<=now()and(r.effective_to is null or r.effective_to>now())and t.effective_from<=now()and(t.effective_to is null or t.effective_to>now())and"authorization".community_member(target_school,target_learner)='student'and"authorization".community_member(target_school,target_parent)='parent'and"authorization".community_member(target_school,target_teacher)='teacher'),false)
$$;
create function internal.require_parent_conversation_tuple(target_learner uuid,target_parent uuid,target_teacher uuid,target_class uuid,target_subject uuid)returns void language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();begin
 perform 1 from app.classes c where c.school_id=school and c.id=target_class and c.status='active'for share;
 perform 1 from app.memberships m where m.school_id=school and m.actor_id in(target_learner,target_parent,target_teacher)order by m.actor_id for share;
 perform 1 from app.enrollments e where e.school_id=school and e.class_id=target_class and e.student_actor_id=target_learner for share;
 perform 1 from app.parent_relationships r where r.school_id=school and r.student_actor_id=target_learner and r.parent_actor_id=target_parent for share;
 perform 1 from app.teacher_assignments t where t.school_id=school and t.class_id=target_class and t.teacher_actor_id=target_teacher and t.subject_id=target_subject for share;
 if not internal.parent_conversation_tuple_allowed(school,target_learner,target_parent,target_teacher,target_class,target_subject)then raise exception 'Current guardian teacher relationship required'using errcode='42501';end if;
end$$;
create function internal.parent_conversation_allowed(target_conversation uuid,moderate boolean default false)returns boolean language sql stable security definer set search_path=''as $$select coalesce(exists(select 1 from app.parent_conversations c where c.school_id="authorization".school_id()and c.id=target_conversation and internal.parent_conversation_tuple_allowed(c.school_id,c.learner_id,c.parent_id,c.teacher_id,c.class_id,c.subject_id)and(case when moderate then"authorization".current_role(c.school_id)='admin'or("authorization".current_role(c.school_id)='teacher'and c.teacher_id="authorization".actor_id())else"authorization".current_role(c.school_id)='admin'or("authorization".current_role(c.school_id)='teacher'and c.teacher_id="authorization".actor_id())or("authorization".current_role(c.school_id)='parent'and c.parent_id="authorization".actor_id())end)),false)$$;
create function internal.parent_conversation_policy_projection()returns jsonb language sql stable security definer set search_path=''as $$select coalesce((select jsonb_build_object('id',p.id,'version',p.version,'enabled',p.enabled,'approvedAt',p.approved_at)from app.parent_conversation_policies p where p.school_id="authorization".school_id()order by p.version desc limit 1),jsonb_build_object('id',"authorization".school_id(),'version',0,'enabled',false,'approvedAt',null))$$;
create function internal.parent_conversation_projection(target_conversation uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare result jsonb;begin
 if not internal.parent_conversation_allowed(target_conversation,false)then raise exception 'Current conversation denied'using errcode='42501';end if;
 select jsonb_build_object('id',c.id,'learnerId',c.learner_id,'parentId',c.parent_id,'teacherId',c.teacher_id,'classId',c.class_id,'subjectId',c.subject_id,'title',c.title,'learnerName',learner.display_name,'parentName',parent.display_name,'teacherName',teacher.display_name,'className',class.name,'academicYearName',year.name,'subjectName',subject.name,'createdAt',c.created_at,'state',coalesce(state.state,'OPEN'),'stateVersion',coalesce(state.version,0),'canModerate',internal.parent_conversation_allowed(c.id,true))into result from app.parent_conversations c join app.people learner on learner.school_id=c.school_id and learner.actor_id=c.learner_id join app.people parent on parent.school_id=c.school_id and parent.actor_id=c.parent_id join app.people teacher on teacher.school_id=c.school_id and teacher.actor_id=c.teacher_id join app.classes class on class.school_id=c.school_id and class.id=c.class_id join app.academic_years year on year.school_id=class.school_id and year.id=class.academic_year_id join app.subjects subject on subject.school_id=c.school_id and subject.id=c.subject_id left join lateral(select s.state,s.version from app.parent_conversation_states s where s.school_id=c.school_id and s.conversation_id=c.id order by s.version desc limit 1)state on true where c.school_id="authorization".school_id()and c.id=target_conversation;
 if result is null then raise exception 'Conversation human context unavailable'using errcode='22023';end if;return result;
end$$;
create function internal.parent_conversation_message_projection(target_message uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare message app.parent_conversation_messages;thread app.parent_conversations;result jsonb;begin
 select m.*into message from app.parent_conversation_messages m where m.school_id="authorization".school_id()and m.id=target_message;if not found or not internal.parent_conversation_allowed(message.conversation_id,false)then raise exception 'Message current access denied'using errcode='42501';end if;if "authorization".current_role(message.school_id)='admin'and not exists(select 1 from app.parent_conversation_reports r where r.school_id=message.school_id and r.message_id=message.id)then raise exception 'Reported message scope required for administrator read'using errcode='42501';end if;select c.*into thread from app.parent_conversations c where c.school_id=message.school_id and c.id=message.conversation_id;
 select jsonb_build_object('id',message.id,'conversationId',message.conversation_id,'senderId',message.sender_id,'senderName',p.display_name,'senderRole',case when message.sender_id=thread.parent_id then'parent'else'teacher'end,'body',case when moderation.action='HIDE'then null else message.body end,'sentAt',message.sent_at,'delivery','DELIVERED_IN_APP','status',case when moderation.action='HIDE'then'HIDDEN'else'VISIBLE'end,'moderationVersion',coalesce(moderation.version,0),'recipientReadAt',(select r.read_at from app.parent_conversation_reads r where r.school_id=message.school_id and r.message_id=message.id and r.reader_id=case when message.sender_id=thread.parent_id then thread.teacher_id else thread.parent_id end))into result from app.people p left join lateral(select m.action,m.version from app.parent_conversation_moderations m where m.school_id=message.school_id and m.message_id=message.id order by m.version desc limit 1)moderation on true where p.school_id=message.school_id and p.actor_id=message.sender_id;return result;
end$$;
create function internal.parent_conversation_command(command_name text,target uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();role_name text:="authorization".current_role("authorization".school_id());thread app.parent_conversations;message app.parent_conversation_messages;reservation jsonb;rid uuid;thread_id uuid;receipt jsonb;policy_version integer;latest integer;fields text[];event_key text;inserted integer;begin
 perform internal.require_context();if not"authorization".has_entitlement(school,'community')or role_name is null or role_name not in('admin','parent','teacher')then raise exception 'School conversation actor denied'using errcode='42501';end if;
 if command_name='policy'then perform pg_advisory_xact_lock(hashtextextended(school::text||':parent-conversation-policy',0));else perform pg_advisory_xact_lock_shared(hashtextextended(school::text||':parent-conversation-policy',0));end if;
 fields:=case command_name when'policy'then array['enabled','expectedVersion','reason','confirmApproval']when'create'then array['learnerId','parentId','teacherId','classId','subjectId','title','body']when'send'then array['body']when'read'then array[]::text[]when'report'then array['reason']when'moderate'then array['action','expectedVersion','reason','confirmModeration']when'state'then array['state','expectedVersion','reason','confirmModeration']else null end;
 if fields is null or payload is null or jsonb_typeof(payload)<>'object'or payload-fields<>'{}'::jsonb or octet_length(payload::text)>30000 then raise exception 'Conversation fields invalid'using errcode='22023';end if;
 if command_name='policy'then
  if role_name<>'admin'then raise exception 'School conversation policy administrator required'using errcode='42501';end if;
  if target is not null or jsonb_typeof(payload->'enabled')is distinct from'boolean'or payload->'confirmApproval'is distinct from'true'::jsonb or jsonb_typeof(payload->'expectedVersion')is distinct from'number'or(payload->>'expectedVersion')!~'^[0-9]+$'or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'Policy human approval required'using errcode='22023';end if;
 elsif command_name='create'then
  if target is not null or role_name not in('parent','teacher')or(role_name='parent'and(payload->>'parentId')::uuid is distinct from actor)or(role_name='teacher'and(payload->>'teacherId')::uuid is distinct from actor)or not internal.parent_conversation_tuple_allowed(school,(payload->>'learnerId')::uuid,(payload->>'parentId')::uuid,(payload->>'teacherId')::uuid,(payload->>'classId')::uuid,(payload->>'subjectId')::uuid)then raise exception 'Exact current guardian teacher source required'using errcode='42501';end if;
  perform internal.require_parent_conversation_tuple((payload->>'learnerId')::uuid,(payload->>'parentId')::uuid,(payload->>'teacherId')::uuid,(payload->>'classId')::uuid,(payload->>'subjectId')::uuid);
 else
  if command_name in('send','state')then thread_id:=target;else select m.*into message from app.parent_conversation_messages m where m.school_id=school and m.id=target;if not found then raise exception 'Conversation message unavailable'using errcode='42501';end if;thread_id:=message.conversation_id;end if;
  select c.*into thread from app.parent_conversations c where c.school_id=school and c.id=thread_id for update;if not found or not internal.parent_conversation_allowed(thread.id,command_name in('moderate','state'))then raise exception 'Exact current conversation denied'using errcode='42501';end if;
  perform internal.require_parent_conversation_tuple(thread.learner_id,thread.parent_id,thread.teacher_id,thread.class_id,thread.subject_id);
  if command_name='moderate'and role_name='admin'and not exists(select 1 from app.parent_conversation_reports r where r.school_id=school and r.message_id=message.id)then raise exception 'Reported message scope required for administrator moderation'using errcode='42501';end if;
  if command_name in('send','read','report')and role_name='admin'then raise exception 'Participant conversation action required'using errcode='42501';end if;
  if command_name='read'and(message.sender_id=actor or(select m.action from app.parent_conversation_moderations m where m.school_id=school and m.message_id=message.id order by m.version desc limit 1)='HIDE') then raise exception 'Recipient read confirmation required'using errcode='22023';end if;
 end if;
 if command_name in('create','send')and(jsonb_typeof(payload->'body')is distinct from'string'or length(btrim(payload->>'body'))not between 1 and 4000)or(command_name='create'and(jsonb_typeof(payload->'title')is distinct from'string'or length(btrim(payload->>'title'))not between 1 and 200))then raise exception 'Actual conversation text required'using errcode='22023';end if;
 if command_name in('report','moderate','state')and(jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 1000)then raise exception 'Safety reason required'using errcode='22023';end if;
 if command_name in('moderate','state')and(payload->'confirmModeration'is distinct from'true'::jsonb or jsonb_typeof(payload->'expectedVersion')is distinct from'number'or(payload->>'expectedVersion')!~'^[0-9]+$'or(command_name='moderate'and(jsonb_typeof(payload->'action')is distinct from'string'or payload->>'action'not in('HIDE','RESTORE')))or(command_name='state'and(jsonb_typeof(payload->'state')is distinct from'string'or payload->>'state'not in('OPEN','PAUSED'))))then raise exception 'Safety review required'using errcode='22023';end if;
 -- Same-key replay rechecks current policy, participant and source before returning any receipt.
 reservation:=internal.begin_command(command_key,'parent-conversation.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then
  if command_name='create'then return internal.parent_conversation_projection((reservation->'response'->>'id')::uuid);elsif command_name='send'then return internal.parent_conversation_message_projection((reservation->'response'->>'id')::uuid);end if;return reservation->'response';
 elsif reservation->>'state'<>'NEW'then raise exception 'Conversation command pending'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(school::text||':parent-conversation-rate:'||actor::text,0));
 if command_name in('create','send','report')and(select count(*)from internal.audit_events a where a.school_id=school and a.actor_id=actor and a.action in('parent-conversation.create','parent-conversation.send','parent-conversation.report')and a.occurred_at>clock_timestamp()-interval'1 minute')>=10 then raise exception 'Conversation rate limited'using errcode='P0003';end if;
 if command_name='policy'then
  select coalesce(max(p.version),0)into policy_version from app.parent_conversation_policies p where p.school_id=school;if(payload->>'expectedVersion')::numeric is distinct from policy_version::numeric then raise exception 'Conversation policy version changed'using errcode='22023';end if;
  insert into app.parent_conversation_policies(school_id,version,enabled,reason,approved_by)values(school,policy_version+1,(payload->>'enabled')::boolean,payload->>'reason',actor)returning id into rid;receipt:=internal.parent_conversation_policy_projection();
 elsif command_name='create'then
  insert into app.parent_conversations(school_id,learner_id,parent_id,teacher_id,class_id,subject_id,title,created_by)values(school,(payload->>'learnerId')::uuid,(payload->>'parentId')::uuid,(payload->>'teacherId')::uuid,(payload->>'classId')::uuid,(payload->>'subjectId')::uuid,payload->>'title',actor)returning id into thread_id;
  insert into app.parent_conversation_messages(school_id,conversation_id,sender_id,body)values(school,thread_id,actor,payload->>'body');rid:=thread_id;receipt:=internal.parent_conversation_projection(rid);
 elsif command_name='send'then
  if(select s.state from app.parent_conversation_states s where s.school_id=school and s.conversation_id=thread.id order by s.version desc limit 1)='PAUSED'then raise exception 'Conversation paused by school'using errcode='42501';end if;
  insert into app.parent_conversation_messages(school_id,conversation_id,sender_id,body)values(school,thread.id,actor,payload->>'body')returning id into rid;receipt:=internal.parent_conversation_message_projection(rid);
 elsif command_name='read'then
  insert into app.parent_conversation_reads(school_id,message_id,reader_id)values(school,message.id,actor)on conflict do nothing;get diagnostics inserted=row_count;rid:=message.id;receipt:=jsonb_build_object('id',rid,'status','READ');
 elsif command_name='report'then
  insert into app.parent_conversation_reports(school_id,message_id,reporter_id,reason)values(school,message.id,actor,payload->>'reason')on conflict(school_id,message_id,reporter_id)do nothing returning id into rid;get diagnostics inserted=row_count;if rid is null then select r.id into rid from app.parent_conversation_reports r where r.school_id=school and r.message_id=message.id and r.reporter_id=actor;end if;receipt:=jsonb_build_object('id',rid,'status','REPORTED');
 elsif command_name='moderate'then
  select coalesce(max(m.version),0)into latest from app.parent_conversation_moderations m where m.school_id=school and m.message_id=message.id;if(payload->>'expectedVersion')::numeric is distinct from latest::numeric then raise exception 'Message moderation changed'using errcode='22023';end if;
  insert into app.parent_conversation_moderations(school_id,message_id,version,action,reason,actor_id)values(school,message.id,latest+1,payload->>'action',payload->>'reason',actor)returning id into rid;receipt:=jsonb_build_object('id',rid,'status',case when payload->>'action'='HIDE'then'HIDDEN'else'VISIBLE'end);
 else
  select coalesce(max(s.version),0)into latest from app.parent_conversation_states s where s.school_id=school and s.conversation_id=thread.id;if(payload->>'expectedVersion')::numeric is distinct from latest::numeric then raise exception 'Conversation state changed'using errcode='22023';end if;
  insert into app.parent_conversation_states(school_id,conversation_id,version,state,reason,actor_id)values(school,thread.id,latest+1,payload->>'state',payload->>'reason',actor)returning id into rid;receipt:=jsonb_build_object('id',rid,'status',payload->>'state');
 end if;
 event_key:='parent-conversation:'||command_name||':'||rid::text||case when command_name='read'then':'||actor::text else''end;
 if command_name not in('read','report')or inserted>0 then perform internal.append_audit('parent-conversation.'||command_name,'parent_conversation',rid,request_id,'succeeded',jsonb_build_object('conversationId',thread_id));perform internal.enqueue_event('parent-conversation.changed','parent_conversation',rid,1,jsonb_build_object('command',command_name,'conversationId',thread_id),event_key);end if;
 perform internal.finish_command(command_key,'parent-conversation.'||command_name,fingerprint,receipt);return receipt;
end$$;
create function internal.parent_conversation_list(resource text,target uuid,filters jsonb)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();role_name text:="authorization".current_role("authorization".school_id());lim integer;cursor_id uuid;learner_filter uuid;items jsonb;begin
 if not"authorization".can_access_school(school)or not"authorization".has_entitlement(school,'community')or role_name is null or role_name not in('admin','teacher','parent')then raise exception 'Current conversation role denied'using errcode='42501';end if;
 if resource is null or resource not in('policy','choices','threads','thread','messages','reports')or filters is null or jsonb_typeof(filters)<>'object'or filters-array['limit','cursor','learnerId']<>'{}'::jsonb then raise exception 'Conversation filters invalid'using errcode='22023';end if;
 lim:=(filters->>'limit')::integer;cursor_id:=(filters->>'cursor')::uuid;learner_filter:=(filters->>'learnerId')::uuid;if lim is null or lim not between 1 and 100 then raise exception 'Bounded conversation page required'using errcode='22023';end if;
 if learner_filter is not null and not"authorization".can_view_person(school,learner_filter)then raise exception 'Conversation child denied'using errcode='42501';end if;
 if resource='policy'then return internal.parent_conversation_policy_projection();end if;
 if not internal.parent_conversation_enabled(school)then raise exception 'School parent conversation policy disabled'using errcode='42501';end if;
 if resource='thread'then return internal.parent_conversation_projection(target);end if;
 if resource='choices'then
  if role_name not in('parent','teacher')then raise exception 'Participant choices required'using errcode='42501';end if;
  with current_choices as materialized(select distinct md5(e.student_actor_id::text||r.parent_actor_id::text||t.teacher_actor_id::text||e.class_id::text||t.subject_id::text)::uuid id,e.student_actor_id learner_id,r.parent_actor_id parent_id,t.teacher_actor_id teacher_id,e.class_id,t.subject_id
   from app.enrollments e join app.parent_relationships r on r.school_id=e.school_id and r.student_actor_id=e.student_actor_id join app.teacher_assignments t on t.school_id=e.school_id and t.class_id=e.class_id where e.school_id=school and(learner_filter is null or e.student_actor_id=learner_filter)and(case when role_name='parent'then r.parent_actor_id=actor else t.teacher_actor_id=actor end)and internal.parent_conversation_tuple_allowed(school,e.student_actor_id,r.parent_actor_id,t.teacher_actor_id,e.class_id,t.subject_id)),bounded as(select*from current_choices where cursor_id is null or id>cursor_id order by id limit lim+1)
  select coalesce(jsonb_agg(jsonb_build_object('id',choice.id,'learnerId',choice.learner_id,'parentId',choice.parent_id,'teacherId',choice.teacher_id,'classId',choice.class_id,'subjectId',choice.subject_id,'learnerName',learner.display_name,'parentName',parent.display_name,'teacherName',teacher.display_name,'className',class.name,'academicYearName',year.name,'subjectName',subject.name)order by choice.id),'[]'::jsonb)into items from bounded choice join app.people learner on learner.school_id=school and learner.actor_id=choice.learner_id join app.people parent on parent.school_id=school and parent.actor_id=choice.parent_id join app.people teacher on teacher.school_id=school and teacher.actor_id=choice.teacher_id join app.classes class on class.school_id=school and class.id=choice.class_id join app.academic_years year on year.school_id=school and year.id=class.academic_year_id join app.subjects subject on subject.school_id=school and subject.id=choice.subject_id;
 elsif resource='threads'then
  select coalesce(jsonb_agg(internal.parent_conversation_projection(c.id)order by c.id),'[]'::jsonb)into items from(select c.id from app.parent_conversations c where c.school_id=school and(cursor_id is null or c.id>cursor_id)and(learner_filter is null or c.learner_id=learner_filter)and internal.parent_conversation_allowed(c.id,false)order by c.id limit lim+1)c;
 else
  if not internal.parent_conversation_allowed(target,resource='reports')then raise exception 'Current thread scope denied'using errcode='42501';end if;
  if learner_filter is not null and not exists(select 1 from app.parent_conversations c where c.school_id=school and c.id=target and c.learner_id=learner_filter)then raise exception 'Thread child filter denied'using errcode='42501';end if;
  if resource='messages'then select coalesce(jsonb_agg(internal.parent_conversation_message_projection(m.id)order by m.id),'[]'::jsonb)into items from(select m.id from app.parent_conversation_messages m where m.school_id=school and m.conversation_id=target and(role_name<>'admin'or exists(select 1 from app.parent_conversation_reports r where r.school_id=m.school_id and r.message_id=m.id))and(cursor_id is null or m.id>cursor_id)order by m.id limit lim+1)m;
  else select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'conversationId',m.conversation_id,'messageId',r.message_id,'reporterName',p.display_name,'reason',r.reason,'createdAt',r.created_at)order by r.id),'[]'::jsonb)into items from(select r.*from app.parent_conversation_reports r join app.parent_conversation_messages m on m.school_id=r.school_id and m.id=r.message_id where r.school_id=school and m.conversation_id=target and(cursor_id is null or r.id>cursor_id)order by r.id limit lim+1)r join app.parent_conversation_messages m on m.school_id=r.school_id and m.id=r.message_id join app.people p on p.school_id=r.school_id and p.actor_id=r.reporter_id;end if;
 end if;
 if octet_length(items::text)>500000 then raise exception 'Conversation page exceeds current review bound'using errcode='22023';end if;
 return jsonb_build_object('items',case when jsonb_array_length(items)>lim then items-lim else items end,'nextCursor',case when jsonb_array_length(items)>lim then items->(lim-1)->>'id'else null end);
end$$;
create function internal.parent_conversation_message_guard()returns trigger language plpgsql security definer set search_path=''as $$begin if not exists(select 1 from app.parent_conversations c where c.school_id=new.school_id and c.id=new.conversation_id and new.sender_id in(c.parent_id,c.teacher_id))then raise exception 'Exact parent teacher message sender required'using errcode='42501';end if;return new;end$$;
create trigger participant_sender_guard before insert on app.parent_conversation_messages for each row execute function internal.parent_conversation_message_guard();
do $$declare tab text;begin foreach tab in array array['parent_conversation_policies','parent_conversations','parent_conversation_messages','parent_conversation_reads','parent_conversation_reports','parent_conversation_moderations','parent_conversation_states']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);execute format('revoke all on app.%I from public,anon,authenticated,service_role,cuevo_api,cuevo_worker',tab);execute format('create trigger immutable_history before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger immutable_truncate before truncate on app.%I for each statement execute function internal.academic_history_immutable()',tab);end loop;end$$;
revoke execute on function internal.require_parent_conversation_tuple(uuid,uuid,uuid,uuid,uuid),internal.parent_conversation_enabled(uuid),internal.parent_conversation_tuple_allowed(uuid,uuid,uuid,uuid,uuid,uuid),internal.parent_conversation_allowed(uuid,boolean),internal.parent_conversation_policy_projection(),internal.parent_conversation_projection(uuid),internal.parent_conversation_message_projection(uuid),internal.parent_conversation_command(text,uuid,jsonb,text,text,text),internal.parent_conversation_list(text,uuid,jsonb),internal.parent_conversation_message_guard()from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.parent_conversation_command(text,uuid,jsonb,text,text,text),internal.parent_conversation_list(text,uuid,jsonb)to cuevo_api;
-- Message bytes remain inside authorized API reads; worker ACK checks immutable audit and never broadcasts content.
do $$declare definition text;anchor text;begin definition:=pg_get_functiondef('internal.process_learner_event(uuid,uuid)'::regprocedure);anchor:='begin'||chr(10);if position(anchor in definition)=0 then raise exception 'Conversation dispatcher shape changed'using errcode='22023';end if;definition:=replace(definition,anchor,'begin'||chr(10)||' if exists(select 1 from internal.outbox_events event where event.id=target_event and event.type=''parent-conversation.changed'')then select*into e from internal.outbox_events where id=target_event for update;if e.state<>''PROCESSING''or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.entity_type<>''parent_conversation''or e.version<>1 or not exists(select 1 from internal.audit_events audit where audit.school_id=e.school_id and audit.actor_id=e.actor_id and audit.entity_id=e.entity_id and audit.entity_type=''parent_conversation''and audit.action=''parent-conversation.''||(e.metadata->>''command'')and (audit.metadata->''conversationId'')is not distinct from(e.metadata->''conversationId''))then raise exception ''Conversation event source invalid''using errcode=''22023'';end if;insert into internal.processed_events(event_id,school_id)values(e.id,e.school_id)on conflict(event_id)do nothing;if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception ''Conversation acknowledgement lease changed''using errcode=''22023'';end if;return jsonb_build_object(''status'',''ACKNOWLEDGED'');end if;'||chr(10));execute definition;end$$;
commit;







